class Solution {
  public int minCost(int[][] grid, int k) {
    int m = grid.length, n = grid[0].length;
    long INF = Long.MAX_VALUE / 4;
    int T = k + 1;
    long[] dist = new long[m * n * 5 * T];
    java.util.Arrays.fill(dist, INF);
    // state = (((cell * 5) + dir) * T + turns); dir 4 = no direction yet
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    int startState = ((0 * 5) + 4) * T;
    dist[startState] = grid[0][0];
    pq.add(new long[] {grid[0][0], startState});
    int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int state = (int) top[1];
      if (top[0] > dist[state]) continue;
      int turns = state % T, rest = state / T, dir = rest % 5, cell = rest / 5;
      int i = cell / n, j = cell % n;
      if (i == m - 1 && j == n - 1) return (int) top[0];
      for (int d = 0; d < 4; d++) {
        int nt = dir == 4 || dir == d ? turns : turns + 1;
        if (nt > k) continue;
        int x = i + dx[d], y = j + dy[d];
        if (x < 0 || y < 0 || x >= m || y >= n) continue;
        int ns = ((x * n + y) * 5 + d) * T + nt;
        long nd = top[0] + grid[x][y];
        if (nd < dist[ns]) {
          dist[ns] = nd;
          pq.add(new long[] {nd, ns});
        }
      }
    }
    return -1;
  }
}
